import{uiMessage,uiLeaf,uiSet,uiSourceLeaf,uiAttributeAttrs,uiHtml,uiNumberLeaf,watchPracticeUi}from './practice-i18n.js';
const ALPHABET_UI_KEYS=Object.freeze({"Арабский алфавит":"alphabetUi.title","Нажмите на букву, чтобы услышать её название. Формы в слове — по ссылке под буквой.":"alphabetUi.tapHint","Скачать алфавит · PDF":"alphabetUi.download","Выберите удобный вариант.":"alphabetUi.chooseFormat","Только буквы":"alphabetUi.lettersOnly","Буквы и названия · 1 страница":"alphabetUi.onePage","Буквы и формы в слове":"alphabetUi.lettersForms","Подробная таблица · 2 страницы":"alphabetUi.twoPages","Формы":"alphabetUi.forms","Проверить себя":"alphabetUi.testYourself","Отметки повторения сохраняются на этом устройстве.":"alphabetUi.deviceNote","Практика":"alphabetUi.practice","Предыдущая":"alphabetUi.previous","Следующая":"alphabetUi.next","Практика завершена":"alphabetUi.complete","Повторяйте буквы и обращайте внимание на точки и соединения.":"alphabetUi.reviewHint","Узнайте букву":"alphabetUi.recognize","Все буквы":"alphabetUi.allLetters","Повторено ✓":"alphabetUi.reviewed","Повторил":"alphabetUi.review","Результат":"alphabetUi.result","Далее":"alphabetUi.nextQuestion","Прогресс не удалось сохранить на этом устройстве.":"alphabetUi.saveFailed","Продолжить":"alphabetUi.continue","Формы буквы":"alphabetUi.formsLabel","28 букв арабского алфавита":"alphabetUi.alphabet28","Отдельно":"alphabetUi.isolated","В начале":"alphabetUi.initial","В середине":"alphabetUi.medial","В конце":"alphabetUi.final","Послушать название":"alphabetUi.listenName","Не удалось включить запись. Проверьте соединение и нажмите ещё раз.":"alphabetUi.audioFailed","Знания":"nav.knowledge","Повторить":"common.retry"});
import{alphabetNameControl,bindAlphabetName,bindAlphabetNames,stopAlphabetName}from './arabic-alphabet-name-audio.js';
import{esc,toast}from './ui.js';
import{read,write}from './storage.js';
import{ARABIC_LETTERS,RIGHT_JOINING,ALPHABET_SOURCE,letterById,letterForms,normalizeAlphabetProgress,reviewLetter,alphabetQuestion}from './arabic-alphabet-core.js';
const key='arabic-alphabet-progress';
const glyph=(s,cls='')=>"<span class=\"alphabet-glyph "+cls+"\" dir=\"rtl\" lang=\"ar\" translate=\"no\">"+esc(s)+"</span>";
const back=(href,text)=>"<a class=\"alphabet-back\" href=\""+href+"\"><img src=\"./assets/arrow-left.svg\" alt=\"\">"+uiSourceLeaf(text,ALPHABET_UI_KEYS)+"</a>";
export function showArabicAlphabet(host,{hash=location.hash}={}){
 let stopLanguage=()=>{};function paint(html){stopLanguage();host.innerHTML=uiHtml(html);stopLanguage=watchPracticeUi(host.firstElementChild);}
 let progress=normalizeAlphabetProgress(read(key,null)),quiz=null;
 const params=new URLSearchParams(hash.split('?')[1]||''),letter=letterById(params.get('letter'));
 function save(p){progress=p;if(!write(key,p))toast(uiMessage('alphabetUi.saveFailed','Прогресс не удалось сохранить на этом устройстве.'));}
 function rules(){return "<details class=\"alphabet-rule\"><summary lang=\"ru\" translate=\"no\">Как соединяются буквы</summary><p lang=\"ru\" translate=\"no\">Арабский текст пишется справа налево. Форма буквы зависит от соединения с соседними буквами.</p><div class=\"alphabet-joining-list\">"+RIGHT_JOINING.map(id=>glyph(letterById(id).char)).join('')+"</div><p lang=\"ru\" translate=\"no\">Эти шесть букв соединяются с предыдущей буквой справа, но не соединяются со следующей слева. Поэтому у них две формы вместо четырёх.</p></details><details class=\"alphabet-rule\"><summary lang=\"ru\" translate=\"no\">Хамза и лям-алиф</summary><div class=\"alphabet-extra-glyphs\">"+['ء','أ','إ','ؤ','ئ'].map(s=>glyph(s)).join('')+"</div><p lang=\"ru\" translate=\"no\">Хамза обозначает отдельный звук. Она может писаться отдельно или на опоре. Здесь показаны варианты её написания.</p><div class=\"alphabet-extra-glyphs\">"+glyph('لا')+glyph('ـلا')+"</div><p lang=\"ru\" translate=\"no\">Лям-алиф — соединение двух букв: лям и алиф. Это не отдельная буква алфавита.</p></details>";}
 function overview(){
 stopAlphabetName();
 paint("<section class=\"alphabet-page\" aria-labelledby=\"alphabet-title\">"+back('#knowledge','Знания')+"<div class=\"alphabet-topline\"><h1 id=\"alphabet-title\" data-i18n=\"alphabetUi.title\">Арабский алфавит</h1><span class=\"alphabet-count\">"+uiLeaf('alphabetUi.reviewProgress','Повторено {count}/28',{count:progress.reviewed.length})+"</span></div><p data-i18n=\"alphabetUi.tapHint\">Нажмите на букву, чтобы услышать её название. Формы в слове — по ссылке под буквой.</p><details class=\"alphabet-rule alphabet-download\"><summary data-i18n=\"alphabetUi.download\">Скачать алфавит · PDF</summary><p data-i18n=\"alphabetUi.chooseFormat\">Выберите удобный вариант.</p><div class=\"alphabet-download-options\"><a class=\"button secondary\" data-alphabet-pdf=\"letters\" href=\"./assets/salah-arabic-letters.pdf\" download=\"SALAH-Arabic-Letters.pdf\" target=\"_blank\" rel=\"noopener\"><strong data-i18n=\"alphabetUi.lettersOnly\">Только буквы</strong><small data-i18n=\"alphabetUi.onePage\">Буквы и названия · 1 страница</small></a><a class=\"button secondary\" data-alphabet-pdf=\"forms\" href=\"./assets/salah-arabic-alphabet.pdf\" download=\"SALAH-Arabic-Alphabet.pdf\" target=\"_blank\" rel=\"noopener\"><strong data-i18n=\"alphabetUi.lettersForms\">Буквы и формы в слове</strong><small data-i18n=\"alphabetUi.twoPages\">Подробная таблица · 2 страницы</small></a></div></details>"+(progress.last?"<a class=\"button secondary\" href=\"#knowledge?view=alphabet&letter="+progress.last+"\">"+uiLeaf('alphabetUi.continue','Продолжить')+' · '+('<span lang="ru" translate="no">'+esc(letterById(progress.last).name)+'</span>')+"</a>":'')+"<div class=\"alphabet-grid\" aria-label=\"28 букв арабского алфавита\" data-i18n-aria-label=\"alphabetUi.alphabet28\">"+ARABIC_LETTERS.map(l=>"<div class=\"alphabet-tile "+(progress.reviewed.includes(l.id)?'is-reviewed':'')+"\">"+alphabetNameControl(l.id,{tile:true})+"<a class=\"alphabet-tile-details\" href=\"#knowledge?view=alphabet&letter="+l.id+'"'+uiAttributeAttrs('aria-label','alphabetUi.letterForms',{name:l.name})+"><span data-i18n=\"alphabetUi.forms\">Формы</span></a></div>").join('')+"</div><button type=\"button\" class=\"button secondary\" data-quiz-start data-i18n=\"alphabetUi.testYourself\">Проверить себя</button>"+rules()+"<p class=\"alphabet-note\" data-i18n=\"alphabetUi.deviceNote\">Отметки повторения сохраняются на этом устройстве.</p><a class=\"alphabet-source\" lang=\"ru\" translate=\"no\" href=\""+ALPHABET_SOURCE+"\" target=\"_blank\" rel=\"noopener\">О соединении букв · Unicode</a></section>");
 bindAlphabetNames(host);
 host.querySelector('[data-quiz-start]').onclick=()=>{quiz={index:0,score:0,start:letterById(progress.last)?.index||0,answered:false};drawQuiz();};window.scrollTo({top:0,behavior:'instant'});
 }
 function study(l){
 stopAlphabetName();
 if(progress.last!==l.id)save({...progress,last:l.id});
 const reviewed=progress.reviewed.includes(l.id);
 paint("<section class=\"alphabet-page\" aria-labelledby=\"alphabet-letter-title\">"+back('#knowledge?view=alphabet','Все буквы')+"<div class=\"alphabet-study\"><div class=\"alphabet-letter-head\">"+alphabetNameControl(l.id)+"<div><h1 id=\"alphabet-letter-title\" tabindex=\"-1\" lang=\"ru\" translate=\"no\">"+esc(l.name)+"</h1><small>"+esc(l.latin)+"</small></div></div><div class=\"alphabet-forms\" aria-label=\"Формы буквы\" data-i18n-aria-label=\"alphabetUi.formsLabel\">"+letterForms(l).map(f=>"<div class=\"alphabet-form\"><small>"+uiSourceLeaf(f.label,ALPHABET_UI_KEYS)+"</small>"+glyph(f.text)+"</div>").join('')+"</div><p class=\"alphabet-note\" lang=\"ru\" translate=\"no\">"+(l.rightOnly?'У этой буквы две формы. Она не соединяется со следующей буквой слева. В середине и конце показана форма с соединением справа.':'Черта показывает место соединения с соседними буквами. Если соседняя буква не соединяется, форма может измениться.')+"</p><div class=\"alphabet-actions\"><button type=\"button\" class=\"button secondary alphabet-review\" data-review aria-pressed=\""+reviewed+"\">"+uiSourceLeaf(reviewed?'Повторено ✓':'Повторил',ALPHABET_UI_KEYS)+"</button><button type=\"button\" class=\"button secondary\" data-quiz-start data-i18n=\"alphabetUi.practice\">Практика</button></div></div><div class=\"alphabet-navigation\"><button type=\"button\" data-letter-prev "+(l.index===0?'disabled':'')+"><span data-i18n=\"alphabetUi.previous\">Предыдущая</span></button><span>"+(l.index+1)+" / 28</span><button type=\"button\" data-letter-next "+(l.index===27?'disabled':'')+"><span data-i18n=\"alphabetUi.next\">Следующая</span></button></div>"+rules()+"<a class=\"alphabet-source\" lang=\"ru\" translate=\"no\" href=\""+ALPHABET_SOURCE+"\" target=\"_blank\" rel=\"noopener\">О соединении букв · Unicode</a></section>");
 bindAlphabetName(host,l.id);
 host.querySelector('[data-review]').onclick=()=>{save(reviewLetter(progress,l.id));study(l);host.querySelector('[data-review]').focus();};
 const go=n=>{const next=ARABIC_LETTERS[l.index+n];if(next)location.hash='knowledge?view=alphabet&letter='+next.id;};
 host.querySelector('[data-letter-prev]').onclick=()=>go(-1);host.querySelector('[data-letter-next]').onclick=()=>go(1);
 host.querySelector('[data-quiz-start]').onclick=()=>{quiz={index:0,score:0,start:l.index,answered:false};drawQuiz();};
 }
 function bindQuizBack(){const link=host.querySelector('a[href="#knowledge?view=alphabet"]');if(link)link.onclick=e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;if(location.hash==='#knowledge?view=alphabet'){e.preventDefault();quiz=null;overview();}};}
 function drawQuiz(){
 stopAlphabetName();
 const q=alphabetQuestion(quiz.index,quiz.start);
 if(!q){paint("<section class=\"alphabet-page\">"+back('#knowledge?view=alphabet','Все буквы')+"<div class=\"alphabet-quiz\"><h1 data-i18n=\"alphabetUi.complete\">Практика завершена</h1><p>"+uiLeaf('alphabetUi.score','Верных ответов: {count} из 8.',{count:quiz.score})+"</p><p data-i18n=\"alphabetUi.reviewHint\">Повторяйте буквы и обращайте внимание на точки и соединения.</p><button class=\"button secondary\" data-quiz-again data-i18n=\"common.retry\">Повторить</button></div></section>");host.querySelector('[data-quiz-again]').onclick=()=>{quiz.index=0;quiz.score=0;quiz.answered=false;drawQuiz();};bindQuizBack();window.scrollTo({top:0,behavior:'instant'});return;}
 paint("<section class=\"alphabet-page\">"+back('#knowledge?view=alphabet','Все буквы')+"<div class=\"alphabet-topline\"><h1 data-i18n=\"alphabetUi.recognize\">Узнайте букву</h1><span class=\"alphabet-count\">"+(quiz.index+1)+" / 8</span></div><div class=\"alphabet-quiz\">"+glyph(q.form.text,'alphabet-quiz-form')+"<div class=\"alphabet-quiz-choices\">"+q.choices.map(c=>"<button type=\"button\" data-answer=\""+c.id+"\">"+glyph(c.char)+"<span lang=\"ru\" translate=\"no\">"+esc(c.name)+"</span><small lang=\"en\" dir=\"ltr\" translate=\"no\">"+esc(c.latin)+"</small></button>").join('')+"</div><div class=\"alphabet-feedback\" role=\"status\" aria-live=\"polite\"></div><button type=\"button\" class=\"button\" data-question-next hidden>"+uiSourceLeaf(quiz.index===7?'Результат':'Далее',ALPHABET_UI_KEYS)+"</button></div></section>");
 host.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quiz.answered)return;quiz.answered=true;const correct=b.dataset.answer===q.target.id;if(correct)quiz.score++;b.classList.add(correct?'is-correct':'is-wrong');host.querySelector('[data-answer="'+q.target.id+'"]').classList.add('is-correct');host.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);uiSet(host.querySelector('.alphabet-feedback'),correct?'alphabetUi.correctLetter':'alphabetUi.thisLetter',correct?'Верно. {name} · {latin}.':'Это буква {name} · {latin}.',{name:q.target.name,latin:q.target.latin});host.querySelector('[data-question-next]').hidden=false;});
 host.querySelector('[data-question-next]').onclick=()=>{if(!quiz.answered)return;quiz.index++;quiz.answered=false;drawQuiz();};bindQuizBack();window.scrollTo({top:0,behavior:'instant'});
 }
 if(letter)study(letter);else overview();
}
